  'Não achei o áudio dessa página. No MyInstants, copie o link do botão de baixar e cole aqui.': 'Couldn’t find the audio on that page. On MyInstants, copy the link from the download button and paste it here.',
  'Esse endereço não é de um arquivo de áudio.': 'That address isn’t an audio file.',
  'Caixa de ideias (como os outros veem)': 'Idea box (how others see it)',
  'É isto que os seus amigos veem aqui embaixo do quarto. O que eles escreverem chega para você como conversa privada, com 💡 na frente — e o Syden já responde agradecendo na hora. Quando a ideia entrar no app, use o joinha na mensagem: do lado deles cai confete e a medalha aparece no perfil.': 'This is what your friends see here below the room. What they write reaches you as a private conversation, with 💡 in front — and Syden replies with a thank-you right away. When the idea makes it into the app, give the message a thumbs-up: confetti falls on their side and the medal shows up on their profile.',
  'Entre numa comunidade para ver as salas.': 'Join a community to see its rooms.',
  'Escreva um pouco mais sobre a sua ideia.': 'Write a little more about your idea.',
