  'Administradores podem apagar mensagens de qualquer pessoa, gerenciar todos os canais, emojis e sons desta comunidade e remover membros. Só o dono dá e tira esse cargo.': 'Admins can delete anyone’s messages, manage every channel, emoji and sound in this community, and remove members. Only the owner gives and takes that role.',
