  'Apaga a comunidade para todo mundo, com os canais, as mensagens, os emojis e os sons dela. Não dá para desfazer.': 'Deletes the community for everyone, with its channels, messages, emojis and sounds. There is no undoing it.',
  'Apagar {comunidade} para todos os {quantos} membros? Os canais, as mensagens, os emojis e os sons somem junto.': 'Delete {comunidade} for all {quantos} members? The channels, the messages, the emojis and the sounds go with it.',
