  'Modificador de voz': 'Voice changer',
  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': 'Changes how other people hear you in the call. It applies right away, you can switch it mid-conversation — and it ends when you leave the room: next time you come in with your own voice.',
