  'Senha definida. Agora dá para entrar com nome e senha também.': 'Password set. Now you can sign in with name and password too.',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'It is what recovers your password and what warns you if something happens to Syden. With no email, a forgotten password has no way back.',
