  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'You do not have any yet. They arrive as a gift or as a reward — for example, when an idea of yours makes it into Syden.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'You came in through an outside service and do not have a password on this account yet. Set one here: it becomes a second way in, and it is what lets you disconnect that service later.',
