  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'The milestones below were chosen so there is no way to reach them alone — each one needs more than one person, over time.',
  'Progresso de {marco}': 'Progress on {marco}',
