  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'Arrows to steer, Space to drift, E to use the item.',
  'Copa da turma': 'The group\'s cup',
  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Carrot Cups the group raced to the end, in Bunny Race.',
  'Bosque': 'Woods',
  'Cânion': 'Canyon',
  'Copa do Repolho': 'Cabbage Cup',
  'Festa dos coelhos': 'Bunny Party',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Five rounds of quick games, each on your own screen: reflexes, aim, memory and sharp eyes. Whoever does best in each round gets more points.',
  'Saque rápido': 'Quick draw',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Wait for the signal and press as fast as you can. Before the signal, you\'re out.',
  'Medidor de força': 'Power meter',
  'Pare a barra o mais perto possível de 100%.': 'Stop the bar as close to 100% as possible.',
  'Parar o relógio': 'Stop the clock',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Stop the clock at exactly 10 seconds. The numbers disappear after 3.',
  'Jogo dos copos': 'Shell game',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Watch where the carrot is and follow the cup. Getting it right faster is worth more.',
  'Siga o coelho': 'Follow the bunny',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Repeat the arrows in order. Each time you get it right, one more comes.',
  'Tiro ao alvo': 'Target practice',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Hit the targets that pop up. Each one is worth one point.',
  'Cedo demais!': 'Too early!',
  'Não valeu': 'Didn\'t count',
  'Sem resposta': 'No answer',
  'Errou': 'Missed',
  'Nenhum troféu ainda. Fique no pódio de um jogo na sala, com a turma.': 'No trophies yet. Finish on the podium of a game in the room, with the group.',
