  'O que a estante de troféus do quarto mostra?': 'What does the trophy shelf in the bedroom show?',
  'O que a minhoca faz pela horta?': 'What does the worm do for the veggie patch?',
  'O que dá para fazer com os móveis do seu quarto?': 'What can you do with the furniture in your bedroom?',
  'O que nasce de uma semente?': 'What grows from a seed?',
  'O que o mascote do Syden veste?': 'What does the Syden mascot wear?',
