  'Oito': 'Eight',
  'Onda no açude': 'Pond Waves',
  'Os livros': 'The books',
  'Os pássaros': 'The birds',
  'Os pódios dos jogos': 'The game podiums',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Listen, repeat the beat in the same rhythm and add one at the end.',
  'Paiol': 'Granary',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Stop each strip with the portrait in place, from top to bottom.',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Stop the three reels on the same picture. Each three of a kind is worth a point.',
  'Pedras': 'Rocks',
  'Pegue a galinha': 'Catch the Hen',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Grab the carrots on the ice and dodge the cabbages.',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Grab a golden carrot and take it to the gate. One is missing: push whoever is carrying one!',
  'Pilotar (para trás, freia e dá ré)': 'Steer (back brakes and reverses)',
  'Plantar': 'Plant them',
  'Ponte do riacho': 'Creek Bridge',
  'Praga na toca': 'Burrow Pests',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'Lock the aim, then the power. Whoever stops closest to the hole wins.',
  'Preta': 'Black',
  'Pronta': 'Ready',
  'Pula o ponteiro': 'Jump the Hand',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'Jump off the swing and land on a leaf. The farthest one is worth more.',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Jump when the hand sweeps past. It keeps getting faster.',
  'Pulo do balanço': 'Swing Jump',
