  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Follow the critters from burrow to burrow. At the end, point to where the one with the balloon is.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Let go of the vine when it\'s in the light strip.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Let go when the turnip points at the field. The faster it spins, the farther it goes.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Climb up to the weathervane. Falling and the crows send you back to the last floor.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Climb the barn over planks, bales and moving beams up to the weathervane at the top, dodging falling tools and crows. In Solo, against the clock and your friends\' ghosts.',
