  '{n} voltas': '{n} laps',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Energy is your life and your boost: hitting the edge drains it, the pink strip recharges it.',
  'A nave explodiu: a energia acabou.': 'The ship exploded: out of energy.',
  'Posição: {posicao} de {total}': 'Position: {posicao} of {total}',
  'Escolher a pista': 'Choose the track',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'A race of carrot ships on a suspended track, much faster than the kart. Energy is your life and your boost: hitting the edge drains it, the pink strip recharges it, and leaving the track means falling. Solo, against the clock and your friends\' ghosts.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'The karts in a closed arena, each with three balloons. Grab the boxes and use the items to pop the others\' balloons: whoever runs out of balloons is out, and the last one left wins.',
  'Esquadrilha da toca': 'Burrow Squadron',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Little carrot planes against the garden pests: dodge the seeds, grab the power-ups and take down the mechanical scarecrow at the end. The group flies the same waves, and the squadron\'s points add up.',
