  'Minigolfe 3D': '3D Mini Golf',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Eight 3D holes with ramps, a castle and a windmill, everyone playing the same one at the same time. Drag to aim and set the power, then let go. Fewest strokes wins.',
  'Ver o buraco de cima': 'View the hole from above',
  'Fora da pista! Mais uma tacada.': 'Off the course! One more stroke.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Drag sideways to aim and down for power, then let go. On the keyboard: the arrows aim, and holding Space sets the power.',
  'Futebol dos coelhos': 'Bunny Soccer',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Small-sided soccer, seen from above. Touch the ball to dribble, hold Space to shoot harder and pass with X. In a room, teams are filled out with bots.',
