  'Caça às pragas da horta': 'Garden Pest Hunt',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Crows and grasshoppers are attacking the garden. Aim and click to hit them before they get away: your ammo is limited, and every wave comes faster. Whoever scores the most wins.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Aim and click the pests before they get away. Each shot uses up a carrot.',
