  'Nenhum amigo jogou esta fase ainda.': 'No friend has played this level yet.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Rain on the garden: everyone gets {n} carrots.',
  '{nome} achou {n} cenouras escondidas.': '{nome} found {n} hidden carrots.',
  '{nome} trocou de lugar com {outro}.': '{nome} swapped places with {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Not enough players: the match ended early, with no trophies.',
  'Saiu antes do fim': 'Left before the end',
  'Jogar o dado': 'Roll the die',
  '{nome} comprou a cenoura dourada!': '{nome} bought the golden carrot!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Buy the golden carrot for {preco} carrots?',
  'Comprar': 'Buy',
  '{nome} chegou à cenoura dourada.': '{nome} reached the golden carrot.',
  'Quantas rodadas?': 'How many rounds?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'The bunnies defend the garden from foxes, crows and a badger. Move together, hit in combos and look out for each other: 1 to 4 players.',
  'Pulo do coelho': 'Bunny Hop',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'A platform race: run, jump and don\'t fall. Solo, against the clock and your friends\' ghosts; with the group, live, on one level or all three.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Swap two neighboring vegetables to match three or more of a kind. The stack keeps rising: don\'t let it reach the top. With the group, chains and combos send crates to the others.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Six mini golf holes, everyone playing the same one at the same time. Pull the ball back and let go to take a shot. Fewest strokes wins.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Players take turns rolling the die and moving around the garden. Collect carrots to buy the golden carrot, and after each round the group plays a microgame. Most golden carrots wins.',
