  'Batalha naval': 'Battleship',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Classic dominoes, 2 to 4 players (with 4, in teams of two). Match the tiles at the ends, and whoever goes out first takes the points left in the others\' hands.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Brazilian truco, with the turned card and the trumps, 1 on 1 or 2 on 2. Call truco, raise to six, nine and twelve, or fold. First to 12 points wins.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brazilian checkers: capturing is mandatory, forward and backward, and the king moves along the whole diagonal. The room watches.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Each player hides their fleet and fires at the other\'s sea. Hit, and you fire again. Whoever sinks the whole fleet first wins. The room watches.',
