  Bispo: 'Bishop',
  'Cozinha da toca': 'Burrow kitchen',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Grab the ingredients from the crates, chop them on the board, cook on the stove and in the oven without burning them, plate them up and hand them in at the window. Everyone gets the same orders: whoever delivers the most dishes in 3 minutes wins.',
  'Pegar ou largar': 'Pick up or put down',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': "This game needs 3D graphics, which didn't open on this device.",
  'Este prato não é o pedido.': "This dish isn't the order.",
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Bunny session',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'One minute at the skate park. Jump, spin, grind the rails and chain tricks into a combo: every extra trick multiplies the points, but bailing loses the whole combo.',
