  'Quadros por segundo': "Frames per second",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "For when the automatic choice gets it wrong: the resolution and frames stay the ones you pick, from start to end of the stream.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "The voice and camera effects made on your computer, without sending anything to a server.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Carrot Commando",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Run and shoot with the group: the carrot blaster aims in eight directions, the grenade clears the way and whoever frees the caged little bunnies gets a power-up. The dragon waits at the end: 1 to 4 people.",
  'Andar e mirar': "Move and aim",
  'Granada': "Grenade",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Burrow Dungeon",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Make your way together through the mushroom king’s burrow: rooms full of critters, a chest with the carrot that flies out and back, switches that need two at once, and the locked door. 1 to 4 people.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Burrow Ring",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Reflex boxing against three computer opponents. Read the tell of each punch, dodge or block, and hit the opening. Hitting when the glove gleams fills the star for the power punch.",
  'Esquivar': "Dodge",
  'Abaixar e defender': "Duck and block",
  'Socar': "Punch",
  'Soco forte': "Power punch",
  'Aperte os socos para levantar!': "Mash the punch keys to get up!",
  'Lutas vencidas: {n}': "Fights won: {n}",
  'Nocaute!': "Knockout!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Star Route",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Bunnies in spaceships across a planet's surface and out into space: shoot, hold fire to lock on, spin to deflect shots and pick a path at the fork. The group flies the same route, and the boss waits at the end.",
  'Pirueta': "Spin",
  'Segure para travar a mira': "Hold to lock on",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Garden Pinball",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "A pinball table in the vegetable garden: hold the plunger, bounce off the cabbages and knock down the three carrots to light up the bunny’s burrow, which releases one more ball. Three balls, and shaking too much locks the table.",
  'Palhetas': "Flippers",
  'Mola': "Plunger",
  'Sacudir': "Nudge",
  'Bola salva!': "Ball saved!",
  'Multibola!': "Multiball!",
  'Mesa travada!': "Tilt!",
  'Cuidado!': "Careful!",
  'Recordes dos amigos': "Friends’ records",
