  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "A city nobody buys goes to auction. Mortgaging a city gives you money, but it doesn't charge rent.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "The hint lights up the piece that moves. A puzzle solved with a hint doesn't score; in the race, it costs 10 seconds.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "The trump is the rank right after the turned card's, and it beats everything. Among them: diamonds, spades, hearts and clubs, the zap.",
  "A última nave de cada volta sai.": "The last ship on each lap is out.",
  "Abaixar": "Duck",
  "Acertos em sequência: {n}": "Solved in a row: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Move by the die and buy the capital where you land. Whoever lands on someone else's city pays rent.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Every row, column and 3 × 3 block has the numbers 1 to 9, with no repeats.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Everyone gets 3 cards. Whoever wins 2 of the 3 rounds takes the hand.",
  "Campeonato": "Championship",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "At 11 points, the team sees its cards and decides whether to play the hand of eleven. First to 12 wins.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "With the whole region, build up to 4 buildings: the rent goes up with each one.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "With stars, the power punch (★) uses them all at once and hurts more.",
  "Dica": "Hint",
  "Dica: este problema não pontua": "Hint: this puzzle won't score",
  "Dica: tira 10 segundos": "Hint: costs 10 seconds",
  "Eliminação": "Elimination",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Place a tile at one end of the table with the same number.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Pick the cell, then the number. The pencil takes notes only you can see.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Dodge the punch and hit right after: that's the counterattack, and it earns a star.",
  "Fora da corrida na volta {n}.": "Out of the race on lap {n}.",
  "Força das cartas": "Card strength",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "The biggest fortune at the end of the rounds wins, or whoever is left.",
  "Iniciante": "Beginner",
  "Mestre": "Master",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "In Streak, each correct answer brings a harder puzzle, and the first mistake ends it.",
  "O número pequeno no botão diz quantos ainda faltam.": "The small number on the button says how many are still missing.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "The five tracks in a row against the computer, with points.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Call truco and the hand is worth 3. Whoever answers accepts, folds or raises to 6, 9 or 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Whoever goes out has no tiles left and takes the points in the others' hands. If it's blocked, whoever has the fewest points in hand takes them.",
