  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "A secret animal is drawn, and everyone guesses others. Each guess shows what matches the secret one: the class, the diet, where it lives and the weight. Whoever gets it in fewer guesses scores more points.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "A secret dinosaur is drawn, and everyone guesses others. Each guess shows what matches the secret one: the period, the diet, the group, the length and where it was found. Whoever gets it in fewer guesses scores more points.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "A secret chemical element is drawn, and everyone guesses others. Each guess shows what matches the secret one: the family, the state of matter, the period, the group and the atomic number. Whoever gets it in fewer guesses scores more points.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "A secret Brazilian state is drawn, and everyone guesses others. Each guess shows the distance and direction to the secret one, the region, the population, the area, the coastline and the border with another country. Whoever gets it in fewer guesses scores more points.",
